-- 06-2-backup.sql — full-row backup of exactly the rows 06-3 may change (generated by split_06.py).
-- Refuses to run unless all 320 reviewed proposals are loaded (row count + content checksum).
-- Copies the affected public.destinations / public.content_translations rows ONCE into the PRIVATE
-- tables audit_backup.rewrites_20261122_destinations / _translations (a second run keeps the first
-- backup), enables RLS and revokes access from public/anon/authenticated. Reads public tables only.
-- Run with psql -v ON_ERROR_STOP=1 -f <file>, or paste the whole file into the SQL editor (one call per file).

begin;

do $$
declare n int; h text;
begin
  if to_regclass('audit_backup.rewrites_20261122_proposals') is null then
    raise exception 'audit_backup.rewrites_20261122_proposals missing: run 06-0-prepare.sql and all 06-1-load-*.sql first';
  end if;
  select count(*), md5(string_agg(concat_ws(chr(31), locale, slug, field, col, coalesce(array_to_string(path, chr(30)), '~'),
                               decision, old_text, new_text),
                     chr(29) order by locale collate "C", slug collate "C", field collate "C"))
    into n, h from audit_backup.rewrites_20261122_proposals;
  if n <> 320 then
    raise exception 'audit_backup.rewrites_20261122_proposals has % rows, expected 320 (a 06-1-load file missing or the table edited by hand?)', n;
  end if;
  if h is distinct from '4b98b4cfb2908f2c3d02ebbd8419fa20' then
    raise exception 'audit_backup.rewrites_20261122_proposals content checksum % differs from the reviewed proposals (4b98b4cfb2908f2c3d02ebbd8419fa20)', h;
  end if;
end $$;

-- Full-row backups, taken once (a second run never overwrites the first backup).
-- Plain copies (no defaults, generated columns, indexes or triggers), so the backup is an exact snapshot.
create table if not exists audit_backup.rewrites_20261122_destinations as
  select * from public.destinations with no data;
create table if not exists audit_backup.rewrites_20261122_translations as
  select * from public.content_translations with no data;

insert into audit_backup.rewrites_20261122_destinations
select d.* from public.destinations d
where d.slug in (select slug from audit_backup.rewrites_20261122_proposals where locale = 'en')
  and not exists (select 1 from audit_backup.rewrites_20261122_destinations b where b.id = d.id);

insert into audit_backup.rewrites_20261122_translations
select t.* from public.content_translations t
where t.entity_type = 'destination'
  and (t.locale, t.entity_id) in (select locale, slug from audit_backup.rewrites_20261122_proposals where locale <> 'en')
  and not exists (select 1 from audit_backup.rewrites_20261122_translations b where b.id = t.id);

alter table audit_backup.rewrites_20261122_proposals    enable row level security;
alter table audit_backup.rewrites_20261122_destinations enable row level security;
alter table audit_backup.rewrites_20261122_translations enable row level security;
revoke all on audit_backup.rewrites_20261122_proposals, audit_backup.rewrites_20261122_destinations,
              audit_backup.rewrites_20261122_translations from public;
do $$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on audit_backup.rewrites_20261122_proposals, audit_backup.rewrites_20261122_destinations, '
                     'audit_backup.rewrites_20261122_translations from %I', r);
    end if;
  end loop;
end $$;


select 'rewrites_20261122_proposals' as backup_table, count(*) as rows from audit_backup.rewrites_20261122_proposals
union all select 'rewrites_20261122_destinations', count(*) from audit_backup.rewrites_20261122_destinations
union all select 'rewrites_20261122_translations', count(*) from audit_backup.rewrites_20261122_translations;

commit;
